"""Create the manuscript figures from data generated by ``generate_data.py``."""

from __future__ import annotations

import argparse
from pathlib import Path

import matplotlib

matplotlib.use("Agg")

import matplotlib.pyplot as plt
import numpy as np

from metrics import lognormal_age_pdf, power_law_age_pdf
from theory import endemic_prevalence


ROOT = Path(__file__).resolve().parents[1]
DEFAULT_DATA = ROOT / "data"
DEFAULT_OUTPUT = ROOT / "figures" / "generated"
COLORS = {"exponential": "r", "lognormal": "g", "powerlaw": "b"}
DISPLAY = {"exponential": "Exponential", "lognormal": "Lognormal", "powerlaw": "Power-law"}


def _style() -> None:
    plt.rcParams.update(
        {
            "font.family": "serif",
            "font.serif": ["Times New Roman", "DejaVu Serif"],
            "axes.labelsize": 13,
            "legend.fontsize": 9,
            "xtick.labelsize": 10,
            "ytick.labelsize": 10,
            "axes.grid": True,
            "grid.alpha": 0.25,
            "figure.dpi": 120,
        }
    )


def _steady(name: str, params: dict, k: int, beta: float) -> float:
    return float(endemic_prevalence(beta, name, k, **params))


def plot_fig3(data_dir: Path, output: Path) -> None:
    data = np.load(data_dir / "fig3_temporal.npz")
    fig, axes = plt.subplots(1, 3, figsize=(12, 3.6), constrained_layout=True)
    cases = {
        "exponential": {"mu": 0.5},
        "lognormal": {"mu": 0.0, "sigma": 1.0},
        "powerlaw": {"alpha": 4.0, "t0": 1.0},
    }
    betas = {"exponential": 0.26, "lognormal": 0.33, "powerlaw": 0.30}
    for axis, name in zip(axes, cases):
        axis.fill_between(
            data["time"], data[f"{name}_low"], data[f"{name}_high"], color=COLORS[name], alpha=0.2
        )
        axis.plot(data["time"], data[f"{name}_mean"], color=COLORS[name], lw=2, label="Simulation")
        axis.axhline(float(data[f"{name}_steady"]), color="k", ls="--", lw=1, label="Mean-field")
        axis.set_xscale("log")
        axis.set_xlim(max(float(data["time"][1]), 1e-2), float(data["time"][-1]))
        axis.set_ylim(0, 1.02)
        axis.set_title(DISPLAY[name])
        axis.set_xlabel(r"$t$")
        axis.set_ylabel(r"$\rho_I(t)$")
        axis.text(
            0.04,
            0.05,
            rf"$\beta={betas[name]:.2f}$" + "\n" + rf"$k=10$",
            transform=axis.transAxes,
        )
    axes[0].legend(loc="best")
    fig.savefig(output / "fig3_density_evolution.png", dpi=300, bbox_inches="tight")
    plt.close(fig)


def plot_fig4(data_dir: Path, output: Path) -> None:
    data = np.load(data_dir / "fig4_confidence.npz")
    fig, axes = plt.subplots(3, 1, figsize=(8, 9), constrained_layout=True)
    for axis, name in zip(axes, COLORS):
        axis.fill_between(
            data["time"], data[f"{name}_low"], data[f"{name}_high"], color=COLORS[name], alpha=0.2, label="95% CI"
        )
        axis.plot(data["time"], data[f"{name}_mean"], color=COLORS[name], lw=2, label="Mean")
        axis.set_xscale("log")
        axis.set_xlim(max(float(data["time"][1]), 1e-2), float(data["time"][-1]))
        axis.set_ylim(0, 1.02)
        axis.set_ylabel(r"$\rho_I(t)$")
        axis.set_title(DISPLAY[name])
        inset = axis.inset_axes([0.66, 0.17, 0.30, 0.28])
        inset.plot(data["time"], data[f"{name}_std"], color="k", lw=1)
        inset.set_xscale("log")
        inset.set_title("std", fontsize=8)
        inset.tick_params(labelsize=6)
    axes[-1].set_xlabel(r"$t$")
    axes[0].legend(loc="best")
    fig.savefig(output / "fig4_mean_ci_std.png", dpi=300, bbox_inches="tight")
    plt.close(fig)


def plot_fig5(data_dir: Path, output: Path) -> None:
    data = np.load(data_dir / "fig5_prevalence.npz")
    fig, axes = plt.subplots(2, 2, figsize=(10, 8), constrained_layout=True)
    for axis, name in zip(axes.flat[:3], COLORS):
        params = {
            "exponential": {"mu": 0.5},
            "lognormal": {"mu": 0.0, "sigma": 1.0},
            "powerlaw": {"alpha": 4.0, "t0": 1.0},
        }[name]
        for k, marker in zip((4, 6, 10), ("o", "s", "^")):
            beta = data[f"{name}_k{k}_beta"]
            mean = data[f"{name}_k{k}_mean"]
            axis.fill_between(
                beta,
                data[f"{name}_k{k}_low"],
                data[f"{name}_k{k}_high"],
                color=COLORS[name],
                alpha=0.12,
            )
            axis.plot(beta, mean, marker=marker, ms=3, color=COLORS[name], label=rf"$k={k}$")
            axis.plot(beta, endemic_prevalence(beta, name, k, **params), color="k", lw=0.9, ls="--")
        axis.set_title(DISPLAY[name])
        axis.set_xlabel(r"$\beta$")
        axis.set_ylabel(r"$\rho_I^\infty$")
        axis.set_ylim(0, 1.02)
        axis.legend()

    errors = np.load(data_dir / "fig5d_errors.npz")
    axis = axes.flat[3]
    for offset, (name, marker) in enumerate(zip(COLORS, ("o", "s", "^"))):
        beta = errors[f"{name}_k10_beta"]
        mean = errors[f"{name}_k10_mean"]
        low = errors[f"{name}_k10_low"]
        high = errors[f"{name}_k10_high"]
        axis.errorbar(
            beta,
            mean,
            yerr=np.vstack((mean - low, high - mean)),
            color=COLORS[name],
            marker=marker,
            ms=3,
            capsize=2,
            lw=1,
            label=DISPLAY[name],
        )
    axis.set_title(r"Error bars, $k=10$, $T=10$")
    axis.set_xlabel(r"$\beta$")
    axis.set_ylabel(r"$\rho_I(T)$")
    axis.set_ylim(0, 1.02)
    axis.legend()
    fig.savefig(output / "fig5_prevalence_threshold.png", dpi=300, bbox_inches="tight")
    plt.close(fig)


def plot_fig6(data_dir: Path, output: Path) -> None:
    data = np.load(data_dir / "fig6_ages.npz")
    cases = {
        "exponential": ({"mu": 0.5}, lambda x, p: p["mu"] * np.exp(-p["mu"] * x)),
        "lognormal": ({"mu": 0.0, "sigma": 1.0}, lambda x, p: lognormal_age_pdf(x, p["mu"], p["sigma"])),
        "powerlaw": ({"alpha": 4.0, "t0": 1.0}, lambda x, p: power_law_age_pdf(x, p["alpha"], p["t0"])),
    }
    fig, axes = plt.subplots(1, 3, figsize=(12, 3.6), constrained_layout=True)
    for axis, name in zip(axes, cases):
        samples = np.asarray(data[name])
        samples = samples[np.isfinite(samples) & (samples > 0)]
        params, pdf = cases[name]
        upper = np.percentile(samples, 99.5)
        bins = np.linspace(0, max(upper, 1e-6), 50)
        axis.hist(samples, bins=bins, density=True, histtype="step", color=COLORS[name], lw=1.5, label="Simulation")
        x = np.linspace(0, bins[-1], 500)
        axis.plot(x, pdf(x, params), "k--", lw=1.2, label="Theory")
        axis.set_title(DISPLAY[name])
        axis.set_xlabel(r"Infected age $\tau$")
        axis.set_ylabel("PDF")
    axes[0].legend()
    fig.savefig(output / "fig6_infected_age_distribution.png", dpi=300, bbox_inches="tight")
    plt.close(fig)


def plot_fig7(data_dir: Path, output: Path) -> None:
    fig, axes = plt.subplots(1, 2, figsize=(10, 4), constrained_layout=True)
    try:
        lognormal = np.load(data_dir / "fig7_lognormal.npz")
        for index, sigma in enumerate(lognormal["sigma"]):
            axes[0].errorbar(
                lognormal["mu"],
                lognormal["mean"][index],
                yerr=lognormal["sem"][index],
                marker="o",
                ms=3,
                capsize=2,
                label=rf"$\sigma={sigma:g}$",
            )
        axes[0].set_xlabel(r"$\mu$")
        axes[0].set_ylabel(r"$\mathbb{E}[T]$")
        axes[0].set_title("Lognormal recovery")
        axes[0].legend()
    except FileNotFoundError:
        axes[0].text(0.5, 0.5, "Run generate_data.py --experiment et-lognormal", ha="center", va="center")
    try:
        powerlaw = np.load(data_dir / "fig7_powerlaw.npz")
        for index, t0 in enumerate(powerlaw["t0"]):
            axes[1].errorbar(
                powerlaw["alpha"],
                powerlaw["mean"][index],
                yerr=powerlaw["sem"][index],
                marker="s",
                ms=3,
                capsize=2,
                label=rf"$t_0={t0:g}$",
            )
        axes[1].set_xlabel(r"$\alpha$")
        axes[1].set_ylabel(r"$\mathbb{E}[T]$")
        axes[1].set_title("Power-law recovery")
        axes[1].legend()
    except FileNotFoundError:
        axes[1].text(0.5, 0.5, "Run generate_data.py --experiment et-powerlaw", ha="center", va="center")
    fig.savefig(output / "fig7_recovery_mean_curves.png", dpi=300, bbox_inches="tight")
    plt.close(fig)


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--figure", choices=["3", "4", "5", "6", "7", "all"], default="all")
    parser.add_argument("--data", type=Path, default=DEFAULT_DATA)
    parser.add_argument("--output", type=Path, default=DEFAULT_OUTPUT)
    args = parser.parse_args()
    args.output.mkdir(parents=True, exist_ok=True)
    _style()
    requested = ["3", "4", "5", "6", "7"] if args.figure == "all" else [args.figure]
    functions = {"3": plot_fig3, "4": plot_fig4, "5": plot_fig5, "6": plot_fig6, "7": plot_fig7}
    for number in requested:
        try:
            functions[number](args.data, args.output)
            print(f"Figure {number} written")
        except FileNotFoundError as exc:
            print(f"Figure {number} skipped: {exc.filename} not found")


if __name__ == "__main__":
    main()

